// ============================================================================
// NODO 3: AGENTE COMERCIAL ENTRENADO (RESPUESTAS NATURALES + PROMPT MAESTRO)
// ============================================================================
const webhookData = $('1. Webhook Web JDStore').first().json.body || {};
const preguntaUsuario = webhookData.mensaje || 'Hola';
const sesionId = webhookData.sesion_id || 'jdstore-session';
const ultimosProductos = webhookData.ultimos_productos_vistos || [];

const dataBD = $input.first().json;
const inst = dataBD.institucion || {};
const tiendas = dataBD.sucursales || [];
const productos = (dataBD.catalogo_productos || []).filter(p => Number(p.stock_total) > 0);
const numWsp = (inst.whatsapp || '51951234567').replace(/\D/g, '');

const textoLower = preguntaUsuario.toLowerCase()
  .replace(/(\d+(?:[.,]\d+)?)\s*mil/g, (_, n) => String(Math.round(parseFloat(n.replace(',', '.')) * 1000)))
  .replace(/\bmil\b/g, '1000');

if (textoLower.includes('como puedo realizar la compra') || textoLower.includes('como compro') || textoLower.includes('cómo compro') || textoLower.includes('quiero comprar') || (textoLower.includes('compra') && textoLower.includes('como'))) {
  const prod = ultimosProductos[0];
  const link = prod
    ? `https://wa.me/${numWsp}?text=${encodeURIComponent('Hola JD Store, deseo comprar ' + prod.nombre)}`
    : `https://wa.me/${numWsp}?text=${encodeURIComponent('Hola JD Store, deseo realizar una compra')}`;
  return [{
    json: {
      ok: true,
      respuesta: `¡Comprar en **JD Store** es muy fácil y seguro! Puedes hacerlo de **3 formas**:\n\n1️⃣ **Por WhatsApp (Atención inmediata):** Haz clic en el botón verde de aquí abajo o escríbenos al **${inst.telefono_central || '951 234 567'}**.\n2️⃣ **Desde la página web:** Haz clic sobre el producto y presiona **Compra vía WhatsApp** o **Añadir al Carrito**.\n3️⃣ **En nuestras tiendas:** Visítanos en **Jr. Noriega 342, Juliaca** o en **Puno**.\n\n💳 **Medios de pago:** Efectivo, **Yape, Plin**, Transferencia (BCP, BBVA, Interbank) y Tarjetas.\n\n[Comprar ahora por WhatsApp](${link})`,
      sesion_id: sesionId,
      origen: 'n8n-trained-agent'
    }
  }];
}

let cat = null;
if (textoLower.includes('impresora') || textoLower.includes('multifuncional') || textoLower.includes('ecotank') || textoLower.includes('pixma') || textoLower.includes('laserjet')) cat = 'impresora';
else if (textoLower.includes('laptop') || textoLower.includes('portatil') || textoLower.includes('portátil') || textoLower.includes('notebook')) cat = 'laptop';
else if (textoLower.includes('monitor') || textoLower.includes('pantalla')) cat = 'monitor';
else if (textoLower.includes('computadora') || textoLower.includes('pc') || textoLower.includes('all-in-one')) cat = 'computadora';
else if (textoLower.includes('tinta') || textoLower.includes('toner') || textoLower.includes('tóner')) cat = 'tinta';
else if (textoLower.includes('teclado') || textoLower.includes('mouse')) cat = 'teclado';
else if (textoLower.includes('memoria') || textoLower.includes('ram') || textoLower.includes('ssd')) cat = 'memoria';

const esGaming = textoLower.includes('gaming') || textoLower.includes('gamer') || textoLower.includes('juego');
if (!cat && esGaming) cat = 'laptop';

let minPrecio = null;
let maxPrecio = null;
const mMin = textoLower.match(/(?:a partir de|mas de|más de|mayor(?:es)? (?:a|de|que)|arriba de|desde|superior(?:es)? a)\s*(?:s\/.?\s*)?(\d+)/);
if (mMin) minPrecio = Number(mMin[1]);
const mMax = textoLower.match(/(?:menos de|menor(?:es)? (?:a|de|que)|hasta|por debajo de|maximo|máximo)\s*(?:s\/.?\s*)?(\d+)/);
if (mMax) maxPrecio = Number(mMax[1]);

let filtrados = [...productos];
if (cat) {
  filtrados = filtrados.filter(p => p.nombre_categoria.toLowerCase().includes(cat) || p.nombre.toLowerCase().includes(cat));
} else if (ultimosProductos.length > 0) {
  filtrados = [...ultimosProductos];
}

if (esGaming && cat === 'laptop') {
  const gamers = filtrados.filter(p => `${p.nombre} ${p.modelo} ${p.descripcion}`.toLowerCase().match(/victus|gamer|gaming|gtx|rtx/));
  if (gamers.length > 0) filtrados = gamers;
}

if (minPrecio !== null) filtrados = filtrados.filter(p => Number(p.precio) >= minPrecio);
if (maxPrecio !== null) filtrados = filtrados.filter(p => Number(p.precio) <= maxPrecio);
filtrados.sort((a, b) => Number(b.precio) - Number(a.precio));

const topOpciones = filtrados.slice(0, 3);
let respuesta = '';
if (topOpciones.length > 0) {
  const top1 = topOpciones[0];
  const link = `https://wa.me/${numWsp}?text=${encodeURIComponent('Hola JD Store, deseo comprar ' + top1.nombre)}`;
  respuesta = `¡Claro! Estas son las mejores opciones disponibles hoy para ti:\n\n` +
    topOpciones.map((p, i) => `${i === 0 ? '🏆 **1.' : i === 1 ? '✨ **2.' : '🔹 **3.'} ${p.nombre}** (${p.modelo}) — **S/ ${Number(p.precio).toFixed(2)}**\n  • ${p.descripcion || p.nombre_marca}\n  • Disponible en tienda (${p.stock_total} und.)`).join('\n\n') +
    `\n\n[Comprar ${top1.nombre} vía WhatsApp](${link})`;
} else {
  respuesta = `¡Con gusto te ayudo! En **${inst.nombre_institucion || 'JD Store'}** tenemos laptops, impresoras, monitores y accesorios listos para entrega inmediata en Juliaca y Puno. ¿Qué equipo estás buscando hoy?`;
}

return [{ json: { ok: true, respuesta, sesion_id: sesionId, origen: 'n8n-trained-agent' } }];
